def scale_complex_vector(N, alpha, X, incX):
	if N < 1:
		return [complex(0)]
	X_ptr = (ctypes.POINTER(ctypes.c_double * (N//2 + 1))) * ctypes.c_int(N)
	for i in range(N // 2 + 1):
		X_ptr[i] = X[2*i].real
	X_ptr_ptr = POINTER(POINTER(c_double)) * N
	for i in range(N):
		X_ptr_ptr[i] = ctypes.pointer(X_ptr[i])
	cblas.cblas_zscal(N, ctypes.c_complex(ctypes.c_double(alpha.real), ctypes.c_double(alpha.imag)), X_ptr_ptr)
