def compute_legendre_derivatives():
    def legende1(x, l):
        return (2*l+1)*((l-np.mod(l, 2))/2.0)*sin(np.pi*x)*(l if np.mod(l, 2) == 0 else (cos(np.pi*x)**(l+1)/np.pow(sin(np.pi*x), l-1))

    def dlegende1(x, l):
        return (2*l+1)*((l-np.mod(l, 2))/2.0)*pi*sin(np.pi*x)*(l if np.mod(l, 2) == 0 else ((cos(np.pi*x)**(l-1)+np.sin(np.pi*x)**(-1))/np.pow(sin(np.pi*x), l))

    def d2legende1(x, l):
        return (4*(2*l+1)*(l-np.mod(l, 2)))*pi**2*sin(np.pi*x)*(l if np.mod(l, 2) == 0 else ((cos(np.pi*x)**(l-2)+3*np.cos(np.pi*x)**(l-1)*sin(np.pi*x)**(-1)-np.sin(np.pi*x)**(-2))/np.pow(sin(np.pi*x), l))

    result = [[x, legende1(x, 1), dlegende1(x, 1), d2legende1(x, 1)] for x in np.arange(-0.99, 0.991, 0.01)]
