class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
    @staticmethod
    def matrix_to_gsl(matrix):
        rows = len(matrix)
        cols = len(matrix[0])
        if rows * cols > 10000:
            raise ValueError('Matrix size exceeds limit')
        gsl_matrix = ctypes.c_double[:] * (rows * cols)
        for i in range(rows):
            for j in range(cols):
                gsl_matrix[i*cols + j] = matrix[i][j]
        return gsl_matrix
    @staticmethod
    def gsl_matrix_to_numpy(gsl_matrix, rows, cols):
        numpy_matrix = np.zeros((rows, cols), dtype=np.float64)
        for i in range(rows):
            for j in range(cols):
                numpy_matrix[i][j] = gsl_matrix[i*cols + j]
        return numpy_matrix
    @staticmethod
    def compute_matrix_exponential(matrix, mode):
        rows = len(matrix)
        cols = len(matrix[0])
        if rows != cols:
            raise ValueError('Matrix is not square')
        if rows > 10000 or cols > 10000:
            raise ValueError('Matrix size exceeds limit')
        gsl_matrix = GSLMatrix.matrix_to_gsl(matrix)
        result = ctypes.POINTER(ctypes.c_double)()
        error = ctypes.c_int()
        gsl.linalg.exponential_ss(gsl_matrix, len(gsl_matrix), mode, result, byref(error))
        if error.value != 0:
            raise ValueError('GSL function returned an error')
        return GSLMatrix.gsl_matrix_to_numpy(result.contents._objects_, rows, cols)

