class gsl_cheb_series:
    def __init__(self, order):
        self.order = order
        self.coeffs = np.zeros(order+1, dtype=np.double)

def chebyshev_coefficients(order, func, a, b):
    f = gsl_function(func)
    c = gsl_cheb_series(order)
    x = np.linspace(a, b, 1000)
    y = [f.eval(xi) for xi in x]
    g = gsl.gsl_cheb_alloc(order+1)
    h = gsl.gsl_chebeval_alloc(x.size)
    p = c.coeffs.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    q = y.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    r = x.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    s = h.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    try:
        gsl.gsl_cheb_y(y.size, a, b, f, g, c.coeffs)
        for i in range(order+1):
            p[i] = c.coeffs[i]
    finally:
        if g: 
            gsl.gsl_cheb_free(g)
        if h: 
            gsl.gsl_chebeval_free(h)

    return c.coeffs.tolist()

