class Taus113State:
    _state = None
    def __init__(self, seed):
        self._state = [0.0, 1.0]
        for i in range(4):
            self._state.append(float((seed >> (16 - i * 2)) & ((1 << 16) - 1)))

    def generate_random_double(self):
        a, b, c = self._state[1], self._state[0] + self._state[1], self._state[1]
        self._state[0], self._state[1] = c, a + b * c
        return (self._state[0] - 0.5) / float(2**53)

def main(seed):
    state = Taus113State(seed)
    random_double = state.generate_random_double()
    json_string = "{"Candidate_solution": str(random_double)}"
    return json.loads(json_string)

