class gsl_matrix(Structure):
    _fields_ = [('data', c_double * (1000, 1000))]

class gsl_vector(Structure):
    _fields_ = [('data', c_double * 1000])

def matrix_to_gsl(matrix):
    mat = gsl_matrix()
    mat.data = (c_double*len(len(matrix)))(*([row[i] for row in matrix] for i in range(len(matrix[0]))))
    return mat

def vector_to_gsl(vector):
    vec = gsl_vector()
    vec.data = (c_double*len(vector))(*vector)
    return vec

def gsl_matrix_to_list(mat):
    return np.array([[mat.data[i + j * len(mat.data[0])] for i in range(len(mat.data[0]))] for j in range(len(mat.data) // len(mat.data[0]))]).tolist()

def gsl_vector_to_list(vec):
    return vec.data.tolist()

def ql_decomposition_and_unpack(A, tau):
    A_gsl = matrix_to_gsl(A)
    tau_gsl = vector_to_gsl(tau)
    q_l_gsl = libgslcblas.gsl_linalg_QL_decomp([A_gsl, tau_gsl], 0)
    q_gsl = gsl_matrix(*q_l_gsl[:2])
    l_gsl = gsl_matrix(*q_l_gsl[2:])
    return gsl_matrix_to_list(q_gsl), gsl_matrix_to_list(l_gsl)

