import ctypes
import numpy as np
from ctypes import c_double, c_int

GSL_DLL = '/usr/local/gsl/lib/libgslcblas.so'
GSL = '/usr/local/gsl/lib/libgsl.so'

gsl = ctypes.CDLL(GSL, mode=ctypes.RTLD_GLOBAL)
ctypes.CDLL(GSL_DLL, mode=ctypes.RTLD_GLOBAL)

class Matrix(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(c_double*ctypes.c_int)),
               ('size1', c_int), ('size2', c_int)]

class Vector(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(c_double)),
               ('size', c_int)]

def matrix_to_gsl(matrix):
    m, n = len(matrix), len(matrix[0])
    data_ptr = ctypes.c_double * (m * n)
    data_ptr[:] = [matrix[i][j] for i in range(m) for j in range(n)]
    return Matrix((data_ptr,), c_int(len(matrix)), c_int(len(matrix[0])))

def vector_to_gsl(vector):
    return Vector((ctypes.c_double * len(vector))([x for x in vector]), c_int(len(vector)))

def gsl_matrix_to_list(gsl_matrix):
    m, n = int(gsl_matrix.size1), int(gsl_matrix.size2)
    return [[gsl_matrix.data[i * n + j] for j in range(n)] for i in range(m)]

def gsl_vector_to_list(gsl_vector):
    size = int(gsl_vector.size)
    return [gsl_vector.data[i] for i in range(size)]

def ql_decomposition_and_unpack(A, tau):
    m, n = len(A), len(A[0])
    A_gsl = matrix_to_gsl(A)
    tau_gsl = vector_to_gsl(tau)
    QL_gsl = gsl.linsolve.A * (gsl.linsolve.A.shape[1], 2*gsl.linsolve.A.shape[1])
gsl_linalg_QL_decomp(QL_gsl, A_gsl, tau_gsl)
gsl_linalg_QL_unpack(QL_gsl)
    Q = gsl_matrix_to_list(QL_gsl.matrix_sub(0, 0))
    L = gsl_matrix_to_list(QL_gsl.matrix_sub(n, 0))
    return Q, L

