def compute_inverse_hyperbolic_functions(x):
    result = (c_float * 3)(0, 0, 0)
    if x < -1:
        result[0] = gsl.acosh(-x)
    elif x > 1:
        result[0] = math.log(x + math.sqrt((x+1)*(x-1)))
    else:
        result[0] = math.log(2)

    if x == 0 or isnan(x):
        result[1] = 0.0
    elif x < -1:
        result[1] = math.log(x + math.sqrt((x+1)*(x-1)))
    else:
        result[1] = math.asinh(0)
    if x == 0 or isnan(x):
        result[2] = 0.0
    elif abs(x) < 1:
        result[2] = math.atan(x)
    else:
        result[2] = math.pi/2
    return (result[0], result[1], result[2])
